from functools import reduce

# ────────────────────────────────────────────────────────────────────────
# %%  [134]

def contar_letras(cadena : str) -> dict[str, int]:
    
    frecuencias = dict() # dicionario vacio
    
    for letra in cadena:
        if letra != " ": # evitar contar espacios de la cadena de texto
            letra = letra.lower() 
            if letra in frecuencias: # si la letra está en el diccionario suma 1 al valor
                frecuencias[letra] += 1
            else:
                frecuencias[letra] = 1 # si no se encunetra crea unaclave con la letra y valor 1
                
    return frecuencias
    


# ────────────────────────────────────────────────────────────────────────
# %%  [132]

texto = "Hola que tal todo"

contar_letras(texto)


