# ## 06 Escribe una función que calcule el factorial de un número de manera recursiva. ##
# 

# ────────────────────────────────────────────────────────────────────────
# %%  [169]

def factorial(x:int) -> int:
    if x == 0 or x == 1: # el factorial de 0 y de 1 es 1
        return 1
    else:
        return x * factorial(x - 1) # devuelve el valor de x multiplicado por el valor del factoria de x -1, el cual calcula de manera recursiva

