def min_masc (caracteres: str) -> list[tuple[str, str]]:
    caracteres = set(caracteres) # set separa los caracteres en elementos
    caracteres = filter(lambda x: x != " ", caracteres)
    return list(map(lambda x: (x.upper(), x.lower()), caracteres))

