# ## 28 Crea una función que busque y devuelva el primer elemento duplicado en una lista dada.
# 

# ────────────────────────────────────────────────────────────────────────
# %%  [56]

def busqueda_rep (lista):
    """Nos devuelve el primer valor que se encuentre repetido en una lista"""
    lista_append = []
    duplicado = []
    for x in lista:
        if x not in lista_append:
            lista_append.append(x)
        else:
            duplicado.append(x)
            break # rompe el bucle for para que solo devuelva un valor, el primer elemento duplicado

    return duplicado


# ────────────────────────────────────────────────────────────────────────
# %%  [57]

