# ## 30 Crea una función que determine si dos palabras son anagramas, es decir, si están formadas por las mismas letras pero en diferente orden. ##

# ────────────────────────────────────────────────────────────────────────
# %%  [58]

def anagrama (palabra_1: str, palabra_2: str):
    """Esta funcion compara dos palabras para ver si son anagramas, es decir, si tienen las mismas letras, pero en distinto orden """
    coinciden = []
    
    palabra_1 = palabra_1.lower()
    palabra_2 = palabra_2.lower()
    
    if len(palabra_1) == len(palabra_2): # comprueba si las palabras tienen el mismo tamaño
        
        for letra in palabra_1: 
                
            if letra in palabra_2:
                coinciden.append(letra) # si la letra está en las dos palabras la añade en la lista coincicden
            else:
                pass
                    
        if len(coinciden) == len(palabra_1): # si coinciden todas las letras es un anagrama
                
            resultado = f"La palabra {palabra_1} y la palabra {palabra_2} son anagramas"
        else: 
            resultado = f"La palabra {palabra_1} y la palabra {palabra_2} no son anagramas"
    else:
            resultado = f"La palabra {palabra_1} y la palabra {palabra_2} no son anagramas"
        
    return resultado


        
   

    

# ────────────────────────────────────────────────────────────────────────
# %%  [59]

anagrama("Pesticida", "Oreja")

