def buscador_empleados(nombre: str, empleados:list[dict]):
    
    for empleado in empleados: # Se crea un bucle que busca los nombres que hay en la lista para poder evaluar si se encunetra el nombre buscado
        if empleado.nombre == nombre: 
            return f"{nombre} trabaja como {empleado.posición}"
            
    return f"{Nombre} no trabaja aquí"
    

