# ## 34 Crea la clase árbol

# ────────────────────────────────────────────────────────────────────────
# %%  [71]

class árbol:
    """ Clase que crea un objeto (árbol) junto con varias funciones para el mantenimiento del árbol """
    def __init__(self, ramas:list = None, tronco: int = 1): # Creación de objeto árbol. De forma predeterminada el árbol tendrá 0 ramas y el tronco medirá 1cm
        self.ramas = [] if ramas is None else list(ramas) # si no se define en número de ramas crea lista vacia 
        self.tronco = tronco
         
    def crecer_tronco(self, crecimiento:int):
        self.tronco += crecimiento 
        return f"El árbol ha crecido {crecimiento} cm"

    
    def nueva_rama(self, n_ramas:int, tamaño_ramas = 1): 
        """ Crea una función donde se definen cuantas ramas le crecen al árbol y el tamaño de las ramas, de forma base cada rama crecerá 1cm"""
        for i in range(n_ramas):
            self.ramas.append(tamaño_ramas)
        return f"Al árbol le han crecido un total de {n_ramas} nuevas rama"
        
    def crecer_ramas(self, C_ramas:int = 1):
        """Crecen las ramas en el tamaño seleccionado, todas las ramas crecen por igual. De base crecrerán 1cm """
        self.ramas = list(map(lambda x: x + C_ramas, self.ramas))
        
        return [f"rama de {rama} cm" for rama in self.ramas]
        
    def quitar_rama(self, p_ramas:int = 0):
        self.ramas.pop(p_ramas) # p_ramas será la posición de la lista de ramas, si no se define la rama que se quiere quitar se quitará la primera rama
        
    def info_arbol(self):
        
        return f"El árbol tiene un total de {len(self.ramas)} ramas ({[f'rama de {rama} cm' for rama in self.ramas]}). El tronco mide {self.tronco} cm"

