# ## 37. Crea una función llamada procesar_texto que procesa un texto según la opción especificada: contar_palabras,reemplazar_palabras, eliminar_palabra . Estas opciones son otras funciones que tenemos que definir primero y llamar dentro de la función procesar_texto .
# 

# ────────────────────────────────────────────────────────────────────────
# Código a seguir:
# 
# - Crear una función contar_palabras para contar el número de veces que aparece cada palabra en el texto. Tiene 
# que devolver un diccionario.
#     
# - Crear una función reemplazar_palabras para remplazar una palabra_original del texto por una palabra_nueva
# Tiene que devolver el texto con el remplazo de palabras.
#     
# - Crear una función eliminar_palabra para eliminar una palabra del texto. Tiene que devolver el texto con la palabra 
# eliminada.
#  
# 
# 
# - Crear la función procesar_texto que tome un texto, una opción(entre "contar", "reemplazar", "eliminar") y un 
# número de argumentos variable según la opción indicada.
# 
# 
# Caso de uso:
# Comprueba el funcionamiento completo de la función 
# procesar_texto

# ────────────────────────────────────────────────────────────────────────
# %%  [98]

def contar_palabras (texto:str) -> dict[str, int]:
    """Cuenta las palabras que se encuentren en un texto dado """
    recuento = {}
    texto = texto.lower().split() # crea una lista con las palabras separadas convirtiendolas en minúsculas
    caracteres= (",",".",";",":","!","¡","?","¿") # cramos lista con caractéres para poder evitar contarlos
    texto_limpio= []

    for palabra in texto: # bucre for para eliminar los simbolos de puntuación
        for caracter in caracteres:
            palabra = palabra.replace(caracter, "") # si la "palabra" es un caracter se elimina
        texto_limpio.append(palabra) # si la palabra no es un caracter la agrega a la lista texto_limpio
        
    for palabra in texto_limpio: 
        if palabra in recuento:
            recuento[palabra] +=1
        else:
            recuento[palabra] = 1
            
    
    return recuento


# ────────────────────────────────────────────────────────────────────────
# %%  [99]

def remplazar_palabras(texto: str, p_reemplazar:str, p_remplazo:str) -> str:
    """esta función reemplaza una palabra seleccionada por otra, todas las veces que aparezca en un texto dado """
    texto = texto.split() #convierte el texto en una lista con todas las palabras en minúscula
    nuevo_texto = []

    for palabra in texto:
        
        palabra_limpia = palabra.strip(".,;:!?¡¿") #evitar errores cuando la palabra esá junto con un signo de puntuación. strip elimina los valores extremos
        puntuacion = palabra[len(palabra_limpia):] #guardamos la puntuación para poder añadirla posteriormente y que el texto no se vea alterado

        
        if palabra_limpia.lower() == p_reemplazar.lower():
            nuevo_texto.append(p_remplazo + puntuacion) # si la palabra iterada es igual a la palabra a reemplazar la sustituye por la palabra remplazo

        else:
            nuevo_texto.append(palabra)

    return " ".join(nuevo_texto) # convierte la lista nuevo texto en un str

# ────────────────────────────────────────────────────────────────────────
# %%  [100]

def elimiar_palabra(texto, p_eliminar):

    texto = texto.split()
    
    texto_filtrado = [palabra for palabra in texto if palabra.lower() != p_eliminar.lower()] # añade solo las palabras que sean distintas a la palabra a eliminar

    return " ".join(texto_filtrado)

# ────────────────────────────────────────────────────────────────────────
# %%  [101]

def procesar_texto (opción :str, *args):
    """ """
    
    if opción.lower() == "contar":
        return contar_palabras(args[0]) # el argumento será el texto

    if opción.lower() == "reemplazar":
        return remplazar_palabras(args[0], args[1], args[2]) # los argumentos erán el texto, la palabra a reemplazar y la palabra reemplazo

    if opción.lower() == "eliminar":
        return eliminar_palabra(args[0], args[1]) # los argumentos serñan el texto y la palabra a eliminar

    else:
        raise TypeError("La opción deberá ser una entre reemplazar, contar o eliminar")
        



